            "csv_wealth_holdings_at_reference_date": "MAJETEK — držby k referenčnímu datu",
            "csv_per_token_summary": "SOUHRN DLE TOKENU",
            "csv_disposals_swaps": "ZCIZENÍ A SWAPY",
            "csv_disposal_lots_cost_basis_audit": "ŠARŽE ZCIZENÍ — auditní stopa nákladové základny",
            "csv_income_rewards_interest": "PŘÍJMY — odměny a úroky",
