            "bears_the_weight_pxa_pxp_together_liquid": "Nese váhu. PXA + PXP dohromady — tekuté a stakované, jedna látka ve dvou skupenstvích. Utvořené z tvůrčí práce.",
            "what_you_actually_hold_pxs_the_body_observed": "Co skutečně držíte. PXS — tělo pozorované skrze mysl. Ne samostatné aktivum; tělo, bdělé.",
            "energy_in_flow_not_a_supply_what": "Energie v toku, ne zásoba. To, co srážka tvaruje, aby se tělo nikdy nezhroutilo pod tím, oč žádá mysl.",
