            "twenty_one_witnesses_elected_by_staked_pxp_each": "Jedenadvacet witnesses, volených stakovaným PXP, publikuje každý své čtení: místní cenu Big Macu, kávy — kupní sílu, ne měnu. Protože reportéry volí kolaterálová základna, je reference modelem, který si základna vytváří sama o sobě.",
