            "a_median_across_the_twenty_one_witnesses_rejects": "Medián napříč jedenadvaceti witnesses odmítne zkorumpovaného reportéra; medián přes 84hodinové okno — tři a půl dne, vzorkované po hodině — odmítne chvilkový výkyv. Nákladné zkorumpovat, pomalé zmanipulovat: robustní konstrukcí, ne důvěrou. Žádná centrální banka, žádný koš MMF, žádný feed BIS.",
