            "1_the_weight": "1× váha",
            "3_floor": "podlaha 3×",
            "10_capacity": "kapacita 10×",
            "delivered": "Dodáno",
            "held_back_by_haircut": "Zadrženo srážkou",
            "when_you_settle_the_body_is_delivered": "Když vypořádáváte, tělo je dodáno jako PXA v okamžiku provedení — částka rovná váze implikované oraclem, vynásobené srážkou. Proto je „podkladové aktivum“ špatné slovo: podklad předpokládá dvě oddělená aktiva, věc a derivát na ni. Jenže supra a atlas nejsou dvě věci. Jsou jedno tělo viděné ve dvou rejstřících — tělo je, co je; supra je to, co mysl říká, že by tělo mělo promítat. Vědomí není něco, co tělo vlastní. Je to tělo, bdělé.",
            "no_monetary_mechanism_removes_risk_a_stablecoin_concentrates": "Žádný měnový mechanismus riziko neodstraní. Mince s fiat rezervou ho koncentruje do integrity této rezervy a solventnosti emitenta. Supra přesouvá toto riziko na volatilitu tvůrčí ekonomiky — rozptyl Atlasu — a integritu konsenzu — spolehlivost kompasu witnesses — a pak ho otevřeně řídí nadměrným zajištěním a nebránící srážkou, místo aby ho skrýval za bráněným číslem.",
            "body_at_the_weight": "Tělo na {{label}} váhy",
            "pixa_supra_pxs": "Pixa Supra · PXS",
            "a_coin_with_its_own_body_mind": "Mince s vlastním tělem, myslí a duší",
            "body_over_the_weight": "Tělo nad váhou",
