            "keep_them_in_a_safe_place_and": "Uchovávejte je na bezpečném místě a nikdy je nesdílejte. Náš tým vás o vaše privátní klíče nikdy nepožádá.",
            "private_key_on_clipboard_warning": "Privátní klíč zkopírován. Schránku mohou číst jiné aplikace a může se synchronizovat mimo toto zařízení — vložte ho hned; za 30 sekund bude přepsán.",
            "could_not_copy": "Nepodařilo se zkopírovat do schránky.",
