            "adding_a_password_provides_extra_security_especi": "Přidání hesla poskytuje dodatečnou bezpečnost, zvlášť u kratších seed frází.",
            "you_are_about_to_request_a_change": "Chystáte se požádat o změnu účtu pro obnovení pro <0>@{{username}}</0>.",
            "nominate_a_trusted_account_a_co_founder": "Nominujte důvěryhodný účet — spoluzakladatele, sesterskou peněženku, kterou ovládáte, nebo kontakt, na který se dostanete mimo platformu — aby vám pomohl získat zpět přístup, pokud by váš owner klíč byl někdy ztracen nebo kompromitován. Proces obnovení používá historii vašeho owner klíče, takže účet pro obnovení sám o sobě nikdy nemůže váš účet zabrat: může vám jen pomoci ho obnovit. Změny nabývají účinnosti po 30denním čekacím okně.",
            "strong_30_day_waiting_period_strong_changing": "<strong>30denní čekací lhůta.</strong> Změna účtu pro obnovení není okamžitá. Nová žádost nabývá účinnosti <strong>30 dní po odvysílání</strong>; do té doby zůstává v platnosti aktuální účet pro obnovení. Opětovné odvysílání během čekacího okna nahradí čekající žádost. Nastavení zpět na aktuální hodnotu čekající změnu zruší.",
            "pick_someone_you_trust_personally_a_co": "Vyberte někoho, komu osobně důvěřujete — spoluzakladatele, sesterský účet, který ovládáte, nebo peněženku, jejíhož vlastníka zastihnete mimo platformu.",
            "generate_a_fresh_seed_phrase_to_derive": "Vygenerujte novou seed frázi a odvoďte z ní nové klíče ke svému účtu. Seed fráze je hlavním klíčem ke všem klíčům vašeho účtu — uchovávejte ji v bezpečí a nikdy ji nesdílejte. Owner klíč se použije k podepsání transakce se změnou klíčů, jakmile níže potvrdíte.",
            "this_will_strong_cancel_any_pending_recovery": "Tím se <strong>zruší jakákoli čekající změna účtu pro obnovení</strong> — znovu se odvysílá stejná hodnota jako váš aktuální účet pro obnovení. 30denní čekající žádost bude nahrazena; aktuální účet pro obnovení zůstává po celou dobu v platnosti.",
            "once_broadcast_the_chain_will_create_a": "Po odvysílání vytvoří chain čekající žádost, která nabude účinnosti za <strong>30 dní</strong>. Váš aktuální účet pro obnovení (<0>@{{currentRecovery}}</0>) zůstává do té doby v platnosti. Budete vyzváni k zadání svého <strong>owner klíče</strong>.",
            "posting_description_1": "Tento klíč se používá pro akce na sociální síti, jako je publikování, komentování a hlasování. Má omezenou sadu oprávnění a nelze ho použít pro peněžní operace.",
            "posting_description_2": "Tímto klíčem se přihlašujte do sociálních sítí postavených na Pixa, jako je Pixagram.com. Uchovávejte ho v bezpečí.",
            "active_description_1": "Tento klíč má dodatečná oprávnění pro citlivější peněžní operace, jako je převod a směna tokenů.",
            "active_description_2": "Při provádění akce související s peněženkou můžete být vyzváni k ověření klíčem Active. Zadávejte klíč Active jen do aplikací, kterým důvěřujete — kdokoli s tímto klíčem vám může vzít tokeny.",
            "owner_description_1": "Klíč Owner je nutný ke změně ostatních klíčů. Má dodatečná oprávnění k obnovení účtu a ke změně ostatních klíčů. Je to nejdůležitější klíč a měl by být bezpečně uložen offline.",
            "memo_description_1": "Klíč Memo je trochu výjimka. Jediné, co dokáže, je šifrovat a dešifrovat soukromé zprávy posílané přes blockchain.",
            "perm_publish_a_post_or_comment": "Publikovat příspěvek nebo komentář",
