            "pixasupra_is_a_type_of_token_which": "PixaSupra je supracoin odkazující na oracle, zaměřený na <0>celosvětové čtení kupní síly reálného zboží</0>. Protokol nebrání žádné číslo a vypořádání dodá to, co kolaterál unese.",
