            "some_figures_could_not_be_valued_in": "Některé údaje nebylo možné ocenit v {{fiat}}: zdroj cen pro ně nevrátil žádný kurz {{fiat}}. Jsou zobrazeny jako „{{na}}“ (nikoli nula) a každý součet, který je zahrnuje, je neúplný. Před použitím tohoto reportu opravte zdroj cen.",
