            "price_basis_snapshot": "{{version}}. Na každé datum byla použita jedna jednotková cena za token (snímek {{asOf}}), takže hodnoty v okamžiku přijetí a zcizení jsou přibližné. Příjem musí být oceněn ke dni přijetí: před podáním přiznání vygenerujte report znovu s historickými cenami.",
            "price_basis_historical": "{{version}}. Každá událost je oceněna cenou ke svému datu; jednotkové ceny na souhrnné stránce jsou hodnoty k {{asOf}} použité pro konečné zůstatky.",
