            "legal_agreement": "Právní smlouva",
            "this_nft_license_agreement_the_agreement": "Tato licenční smlouva k NFT (dále jen „Smlouva“) stanoví přizpůsobitelné podmínky, za nichž tvůrce (dále jen „Autor“) uděluje určitá práva nabyvateli (dále jen „Držitel“) nezastupitelných tokenů (NFT) spojených s konkrétní kolekcí digitálních uměleckých děl (dále jen „Kolekce“). Cílem této Smlouvy je nabídnout flexibilní, transparentní a spravedlivý licenční rámec, který se dokáže přizpůsobit různým případům užití, obchodním modelům a uměleckým záměrům, a zároveň zajistit, že osobnostní práva Autora zůstanou nedotčena a plně zachována. Tato struktura je určena zejména tvůrcům NFT, kteří chtějí držitelům svých digitálních aktiv poskytnout práva užití upravená na míru, a umožnit tak řadu způsobů interakce s dílem a jeho využití v závislosti na preferencích zvolených Autorem.",
